/**
 * Unit tests for BasicSerializerFactory#buildIndexedListSerializer.
 */
public class BasicSerializerFactory_buildIndexedListSerializer_TriageGen2Test {

    private BasicSerializerFactory factory;
    private TypeFactory typeFactory;
    private JavaType elemType;
    private TypeSerializer vts;
    private JsonSerializer<Object> valueSerializer;

    @Before
    public void setUp() {
        // BasicSerializerFactory has a protected constructor requiring SerializerFactoryConfig.
        // We use a concrete implementation or mock it. Since it's a factory, we can use an anonymous subclass.
        factory = new BasicSerializerFactory(new SerializerFactoryConfig()) {
            @Override
            protected Iterable<Serializers> customSerializers() {
                return null;
            }
        };

        typeFactory = TypeFactory.defaultInstance();
        elemType = typeFactory.constructType(String.class);
        vts = mock(TypeSerializer.class);
        valueSerializer = new StdSerializer<Object>(Object.class) {
            @Override
            public void serialize(Object value, com.fasterxml.jackson.core.JsonGenerator gen, SerializerProvider serializers) 
                    throws java.io.IOException {
                gen.writeString(value.toString());
            }
        };
    }

    @Test
    public void testBuildIndexedListSerializer_Success() {
        // Arrange
        boolean staticTyping = true;

        // Act
        ContainerSerializer<?> result = factory.buildIndexedListSerializer(elemType, staticTyping, vts, valueSerializer);

        // Assert
        assertNotNull("The returned serializer should not be null", result);
        assertTrue("The returned serializer should be an instance of IndexedListSerializer", 
                result instanceof IndexedListSerializer);

        // Since IndexedListSerializer fields are private/protected, we verify behavior or type.
        // The method is a simple wrapper/factory method.
        assertEquals("Type of the returned serializer should match the expected class", 
                IndexedListSerializer.class, result.getClass());
    }

    @Test
    public void testBuildIndexedListSerializer_WithFalseStaticTyping() {
        // Arrange
        boolean staticTyping = false;

        // Act
        ContainerSerializer<?> result = factory.buildIndexedListSerializer(elemType, staticTyping, vts, valueSerializer);

        // Assert
        assertNotNull(result);
        assertTrue(result instanceof IndexedListSerializer);
    }

    @Test
    public void testBuildIndexedListSerializer_WithNullParams() {
        // Note: The implementation of IndexedListSerializer might throw NullPointerException 
        // if certain parameters are null depending on its internal constructor logic.
        // This test checks if the factory method propagates/handles nulls as expected.

        try {
            factory.buildIndexedListSerializer(null, true, vts, valueSerializer);
        } catch (NullPointerException e) {
            // Expected if IndexedListSerializer constructor doesn't allow null elemType
        }

        try {
            factory.buildIndexedListSerializer(elemType, true, null, valueSerializer);
        } catch (NullPointerException e) {
            // Expected if IndexedListSerializer constructor doesn't allow null vts
        }

        try {
            factory.buildIndexedListSerializer(elemType, true, vts, null);
        } catch (NullPointerException e) {
            // Expected if IndexedListSerializer constructor doesn't allow null valueSerializer
        }
    }

    @Test
    public void testBuildIndexedListSerializer_DifferentElementType() {
        // Arrange
        JavaType intType = typeFactory.constructType(Integer.class);
        boolean staticTyping = true;

        // Act
        ContainerSerializer<?> result = factory.buildIndexedListSerializer(intType, staticTyping, vts, valueSerializer);

        // Assert
        assertNotNull(result);
        assertTrue(result instanceof IndexedListSerializer);
    }
}
